    overflow-x: hidden;
    background-image: 
        radial-gradient(circle at 15% 50%, rgba(139, 92, 246, 0.15), transparent 25%),
        radial-gradient(circle at 85% 30%, rgba(59, 130, 246, 0.15), transparent 25%);
}

a {
    text-decoration: none;
    color: inherit;
}

/* Glassmorphism Utilities */
.glass-card {
    background: var(--bg-card);
    backdrop-filter: var(--glass-blur);
    -webkit-backdrop-filter: var(--glass-blur);
    border: 1px solid var(--border-color);
    border-radius: 16px;
    padding: 2rem;
    transition: transform 0.3s ease, background 0.3s ease;
}

.glass-card:hover {
    background: var(--bg-card-hover);
    transform: translateY(-5px);
}

/* Navbar */
.navbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1.5rem 5%;
    position: fixed;
    width: 100%;
    top: 0;
    z-index: 100;
    background: rgba(10, 10, 15, 0.8);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--border-color);
}

.logo {
    font-size: 1.5rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.nav-links {
    display: flex;
    align-items: center;
    gap: 2rem;
    font-weight: 600;
}

.nav-links a:hover {
    color: var(--accent-1);
}

/* Buttons */
.btn-primary, .btn-primary-small {
    background: linear-gradient(135deg, var(--accent-1), var(--accent-2));
    color: white;
    border: none;
    border-radius: 8px;
    font-weight: 600;
    cursor: pointer;
    transition: opacity 0.2s;
}

.btn-primary {
    padding: 1rem 2rem;
    font-size: 1.1rem;
}

.btn-primary-small {
    padding: 0.5rem 1.2rem;
}

.btn-secondary {
    background: rgba(255, 255, 255, 0.1);
    color: white;
    padding: 1rem 2rem;
    border-radius: 8px;
    font-weight: 600;
    border: 1px solid var(--border-color);
    transition: background 0.2s;
}

.btn-secondary:hover {
    background: rgba(255, 255, 255, 0.2);
}

.btn-primary:hover, .btn-primary-small:hover {
    opacity: 0.9;
}

/* Hero Section */
.hero {
    display: flex;
    align-items: center;
    justify-content: space-between;
    min-height: 100vh;
    padding: 0 5%;
    gap: 4rem;
    padding-top: 80px;
}

.hero-content {
    flex: 1;
}

.hero h1 {
    font-size: 4rem;
    line-height: 1.1;
    margin-bottom: 1.5rem;
    font-weight: 800;
    letter-spacing: -1px;
}

.gradient-text {
    background: linear-gradient(135deg, var(--accent-1), var(--accent-2));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.hero p {
    font-size: 1.2rem;
    color: var(--text-muted);
    margin-bottom: 2.5rem;
    max-width: 500px;
}

.hero-buttons {
    display: flex;
    gap: 1rem;
}

.hero-visual {
    flex: 1;
    display: flex;
    justify-content: center;
}

/* Mockup */
.mockup {
    width: 100%;
    max-width: 500px;
    padding: 0;
    overflow: hidden;
}

.mockup:hover { transform: none; background: var(--bg-card); }

.mockup-header {
    background: rgba(0, 0, 0, 0.5);
    padding: 12px 20px;
    display: flex;
    gap: 8px;
    border-bottom: 1px solid var(--border-color);
}

.dot {
    width: 12px;
    height: 12px;
    border-radius: 50%;
}
.red { background: #ff5f56; }
.yellow { background: #ffbd2e; }
.green { background: #27c93f; }

.mockup-body {
    padding: 20px;
    font-family: monospace;
    font-size: 0.9rem;
}

.mockup-body p {
    margin-bottom: 10px;
}
.sys { color: #a78bfa; }
.usr { color: #9ca3af; }

/* Features */
.features {
    padding: 5rem 5%;
    text-align: center;
}

.features h2 {
    font-size: 2.5rem;
    margin-bottom: 3rem;
}

.feature-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 2rem;
}

.feature-card .icon {
    font-size: 2.5rem;
    margin-bottom: 1rem;
}

.feature-card h3 {
    margin-bottom: 1rem;
    font-size: 1.2rem;
}

.feature-card p {
    color: var(--text-muted);
    font-size: 0.95rem;
}

/* Download Section */
.download {
    padding: 5rem 5%;
    text-align: center;
    background: linear-gradient(to bottom, transparent, rgba(139, 92, 246, 0.05));
}

.download h2 {
    font-size: 2.5rem;
    margin-bottom: 1rem;
}

.download > p {
    color: var(--text-muted);
    margin-bottom: 4rem;
}

.download-grid {
    display: flex;
    justify-content: center;
    gap: 2rem;
    flex-wrap: wrap;
}

.download-card {
    width: 280px;
    display: flex;
    flex-direction: column;
    align-items: center;
}

.os-icon {
    font-size: 3rem;
    margin-bottom: 1rem;
}

.download-card h3 {
    font-size: 1.5rem;
    margin-bottom: 0.5rem;
}

.download-card p {
    color: var(--text-muted);
    font-size: 0.9rem;
    margin-bottom: 2rem;
}

.btn-download {
    width: 100%;
    padding: 0.8rem;
    background: rgba(255,255,255,0.1);
    color: white;
    border: 1px solid var(--border-color);
    border-radius: 8px;
    cursor: pointer;
    font-weight: 600;
    transition: background 0.2s;
}

.download-card:hover .btn-download {
    background: var(--accent-1);
    border-color: var(--accent-1);
}

footer {
    text-align: center;
    padding: 2rem;
    border-top: 1px solid var(--border-color);
    color: var(--text-muted);
    font-size: 0.9rem;
}

/* Responsive */
@media (max-width: 768px) {
    .hero {
        flex-direction: column;
        text-align: center;
        padding-top: 120px;
    }
    .hero-buttons {
        justify-content: center;
    }
    .hero h1 {
        font-size: 3rem;
    }
}
